func TestGettersVanityNameserver(t *testing.T) {
	t.Run("GetDomainName", func(t *testing.T) {
		t.Parallel()
		// Arrange
		obj := &VanityNameserver{}
		var expected string
		obj.DomainName = expected

		// Act & Assert
		assert.Equal(t, expected, obj.GetDomainName(), "getter should return the property value")
	})

	t.Run("GetDomainName_NilReceiver", func(t *testing.T) {
		t.Parallel()
		var obj *VanityNameserver
		// Should not panic - getters should handle nil receiver gracefully
		defer func() {
			if r := recover(); r != nil {
				t.Errorf("Getter panicked on nil receiver: %v", r)
			}
		}()
		_ = obj.GetDomainName() // Should return zero value
	})

	t.Run("GetHostname", func(t *testing.T) {
		t.Parallel()
		// Arrange
		obj := &VanityNameserver{}
		var expected string
		obj.Hostname = expected

		// Act & Assert
		assert.Equal(t, expected, obj.GetHostname(), "getter should return the property value")
	})

	t.Run("GetHostname_NilReceiver", func(t *testing.T) {
		t.Parallel()
		var obj *VanityNameserver
		// Should not panic - getters should handle nil receiver gracefully
		defer func() {
			if r := recover(); r != nil {
				t.Errorf("Getter panicked on nil receiver: %v", r)
			}
		}()
		_ = obj.GetHostname() // Should return zero value
	})

	t.Run("GetIps", func(t *testing.T) {
		t.Parallel()
		// Arrange
		obj := &VanityNameserver{}
		var expected []string
		obj.Ips = expected

		// Act & Assert
		assert.Equal(t, expected, obj.GetIps(), "getter should return the property value")
	})

	t.Run("GetIps_NilValue", func(t *testing.T) {
		t.Parallel()
		// Arrange
		obj := &VanityNameserver{}
		obj.Ips = nil

		// Act & Assert
		assert.Nil(t, obj.GetIps(), "getter should return nil when property is nil")
	})

	t.Run("GetIps_NilReceiver", func(t *testing.T) {
		t.Parallel()
		var obj *VanityNameserver
		// Should not panic - getters should handle nil receiver gracefully
		defer func() {
			if r := recover(); r != nil {
				t.Errorf("Getter panicked on nil receiver: %v", r)
			}
		}()
		_ = obj.GetIps() // Should return zero value
	})

}

